)

const defaultCatalogBaseURL = "https://documentdrivendx.github.io/agent/catalog"

func cmdCatalog(workDir string, args []string) int {
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "usage: ddx-agent catalog <show|models|observations|check|update|update-pricing> [flags]")
		return 2
	}
	switch args[0] {
	case "show":
		return cmdCatalogShow(workDir, args[1:])
	case "models":
		return cmdCatalogModels(workDir, args[1:])
	case "observations":
		return cmdCatalogObservations(workDir, args[1:])
	case "check":
		return cmdCatalogCheck(workDir, args[1:])
	case "update":
		return cmdCatalogUpdate(workDir, args[1:])
	case "update-pricing":
		return cmdCatalogUpdatePricing(workDir, args[1:])
	default:
		fmt.Fprintf(os.Stderr, "error: unknown catalog subcommand %q\n", args[0])
		return 2
	}
}

func cmdCatalogShow(workDir string, args []string) int {
	fs := flag.NewFlagSet("catalog show", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	if err := fs.Parse(args); err != nil {
		return 2
	}

	cfg, catalog, manifestPath, err := loadCatalogRuntime(workDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}
	_ = cfg

	meta := catalog.Metadata()
	fmt.Printf("source: %s\n", meta.ManifestSource)
	fmt.Printf("manifest_path: %s\n", manifestPath)
	fmt.Printf("schema_version: %d\n", meta.ManifestVersion)
	fmt.Printf("catalog_version: %s\n", blankIfEmpty(meta.CatalogVersion))

	if profiles := catalog.SamplingProfileNames(); len(profiles) > 0 {
		fmt.Printf("sampling_profiles: %s\n", strings.Join(profiles, ", "))
	} else {
		fmt.Println("sampling_profiles: (none — using server defaults; run 'ddx-agent catalog update' if missing)")
	}

	for _, ref := range []string{"code-high", "code-medium", "code-economy"} {
		fmt.Printf("%s:\n", ref)
		printResolvedSurface(catalog, ref, modelcatalog.SurfaceAgentAnthropic)
		printResolvedSurface(catalog, ref, modelcatalog.SurfaceAgentOpenAI)
	}
	return 0
}

// catalogModelRow is the JSON representation of one v4 models: map entry.
type catalogModelRow struct {
	ID                string  `json:"id"`
	ProviderSystem    string  `json:"provider_system,omitempty"`
	CostInputPerMTok  float64 `json:"cost_input_per_mtok,omitempty"`
	CostOutputPerMTok float64 `json:"cost_output_per_mtok,omitempty"`
	SWEBenchVerified  float64 `json:"swe_bench_verified,omitempty"`
	OpenRouterRefID   string  `json:"openrouter_ref_id,omitempty"`
	SpeedTokensPerSec float64 `json:"speed_tokens_per_sec,omitempty"`
}

func cmdCatalogModels(workDir string, args []string) int {
	fs := flag.NewFlagSet("catalog models", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	modelFlag := fs.String("model", "", "Show details for a specific model ID")
	formatFlag := fs.String("format", "", "Output format: json")
	if err := fs.Parse(args); err != nil {
		return 2
	}

	_, catalog, _, err := loadCatalogRuntime(workDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	modelsMap := catalog.AllModels()
	if len(modelsMap) == 0 {
		fmt.Println("no model entries in catalog (requires v4+ manifest)")
		return 0
	}

	// Collect model IDs.
	ids := make([]string, 0, len(modelsMap))
	if *modelFlag != "" {
		entry, ok := catalog.LookupModel(*modelFlag)
		if !ok {
			fmt.Fprintf(os.Stderr, "error: model %q not found in catalog\n", *modelFlag)
			return 1
		}
		modelsMap = map[string]modelcatalog.ModelEntry{*modelFlag: entry}
		ids = append(ids, *modelFlag)
	} else {
		for id := range modelsMap {
			ids = append(ids, id)
		}
	}
	sort.Strings(ids)

	if *formatFlag == "json" {
		rows := make([]catalogModelRow, 0, len(ids))
		for _, id := range ids {
			e := modelsMap[id]
			rows = append(rows, catalogModelRow{
				ID:                id,
				ProviderSystem:    e.ProviderSystem,
				CostInputPerMTok:  catalogCostInputPerM(e),
				CostOutputPerMTok: catalogCostOutputPerM(e),
				SWEBenchVerified:  e.SWEBenchVerified,
				OpenRouterRefID:   catalogOpenRouterID(e),
				SpeedTokensPerSec: e.SpeedTokensPerSec,
			})
		}
		data, err := json.MarshalIndent(rows, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: marshal json: %v\n", err)
			return 1
		}
		fmt.Println(string(data))
		return 0
	}

	if *modelFlag != "" && len(ids) == 1 {
		// Detailed view for a single model.
		id := ids[0]
		e := modelsMap[id]
		fmt.Printf("id:                    %s\n", id)
		if e.ProviderSystem != "" {
			fmt.Printf("provider_system:       %s\n", e.ProviderSystem)
		}
		if inputCost := catalogCostInputPerM(e); inputCost > 0 {
			fmt.Printf("cost_input_per_m:      $%.2f\n", inputCost)
			fmt.Printf("cost_output_per_m:     $%.2f\n", catalogCostOutputPerM(e))
		}
		if e.SWEBenchVerified > 0 {
			fmt.Printf("swe_bench_verified:    %.1f\n", e.SWEBenchVerified)
		}
		if e.SpeedTokensPerSec > 0 {
			fmt.Printf("speed_tokens_per_sec:  %.1f\n", e.SpeedTokensPerSec)
		}
		if openRouterID := catalogOpenRouterID(e); openRouterID != "" {
			fmt.Printf("openrouter_id:         %s\n", openRouterID)
		}
		return 0
	}

	// Table view.
	fmt.Printf("%-28s %-12s %-12s %-12s %s\n", "MODEL", "PROVIDER", "INPUT/MTok", "OUTPUT/MTok", "SWE-bench")
	for _, id := range ids {
		e := modelsMap[id]
		inputStr := "-"
		outputStr := "-"
		sweStr := "-"
		if inputCost := catalogCostInputPerM(e); inputCost > 0 {
			inputStr = fmt.Sprintf("$%.2f", inputCost)
		}
		if outputCost := catalogCostOutputPerM(e); outputCost > 0 {
			outputStr = fmt.Sprintf("$%.2f", outputCost)
		}
		if e.SWEBenchVerified > 0 {
			sweStr = fmt.Sprintf("%.1f", e.SWEBenchVerified)
		}
		fmt.Printf("%-28s %-12s %-12s %-12s %s\n",
			id,
			e.ProviderSystem,
			inputStr,
			outputStr,
			sweStr,
		)
	}
	return 0
}

func catalogCostInputPerM(e modelcatalog.ModelEntry) float64 {
	if e.CostInputPerM != 0 {
		return e.CostInputPerM
	}
	return e.CostInputPerMTok
}

func catalogCostOutputPerM(e modelcatalog.ModelEntry) float64 {
	if e.CostOutputPerM != 0 {
		return e.CostOutputPerM
	}
package agentcli

import (
	"bufio"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/corpus"
)

// corpusRoot is the conventional location for the curated benchmark corpus.
// It is intentionally pinned to the repo (workDir) under scripts/beadbench
// so the corpus travels with the agent codebase, not with end-user state.
const corpusRoot = "scripts/beadbench"

func cmdCorpus(workDir string, args []string) int {
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "usage: ddx-agent corpus <promote|validate|list> [flags]")
		return 2
	}
	switch args[0] {
	case "promote":
		return cmdCorpusPromote(workDir, args[1:])
	case "validate":
		return cmdCorpusValidate(workDir, args[1:])
	case "list":
		return cmdCorpusList(workDir, args[1:])
	default:
		fmt.Fprintf(os.Stderr, "error: unknown corpus subcommand %q\n", args[0])
		return 2
	}
}

func cmdCorpusValidate(workDir string, args []string) int {
	fs := flag.NewFlagSet("corpus validate", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	if err := fs.Parse(args); err != nil {
		return 2
	}
	root := filepath.Join(workDir, corpusRoot)
	if err := corpus.Validate(root); err != nil {
		fmt.Fprintf(os.Stderr, "corpus invalid:\n%s\n", err)
		return 1
	}
	fmt.Println("corpus: ok")
	return 0
}

func cmdCorpusList(workDir string, args []string) int {
	fs := flag.NewFlagSet("corpus list", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	jsonOut := fs.Bool("json", false, "Emit JSON instead of a human-readable table")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	root := filepath.Join(workDir, corpusRoot)
	loaded, err := corpus.Load(root)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		return 1
	}
	if *jsonOut {
		out, _ := json.MarshalIndent(loaded.Index, "", "  ")
		fmt.Println(string(out))
		return 0
	}
	fmt.Printf("%-22s %-8s %-32s %s\n", "BEAD", "KIND", "TAG", "PROMOTED")
	for _, e := range loaded.Index.Beads {
		kind := "capability"
		tag := e.Capability
		if e.FailureMode != "" {
			kind = "failure_mode"
			tag = e.FailureMode
		}
		fmt.Printf("%-22s %-8s %-32s %s by %s\n", e.BeadID, kind, tag, e.Promoted, e.PromotedBy)
	}
	return 0
}

func cmdCorpusPromote(workDir string, args []string) int {
	fs := flag.NewFlagSet("corpus promote", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	capability := fs.String("capability", "", "Capability tag (must be in capabilities.yaml)")
	failureMode := fs.String("failure-mode", "", "Failure-mode tag (must be in capabilities.yaml)")
	difficulty := fs.String("difficulty", "", "easy|medium|hard")
	promptKind := fs.String("prompt-kind", "", "implement-with-spec|port-by-analogy|debug-and-fix|review")
	notes := fs.String("notes", "", "Free-text notes describing why the bead is instructive")
	baseRev := fs.String("base-rev", "", "Pre-change revision (defaults to bead.parent_commit_sha)")
	knownGoodRev := fs.String("known-good-rev", "", "Resolution revision (defaults to bead.closing_commit_sha)")
	projectRoot := fs.String("project-root", "", "Repository root for the bead (defaults to workDir)")
	promotedBy := fs.String("promoted-by", "", "Identity recording the promotion (defaults to $USER)")
	yes := fs.Bool("yes", false, "Skip the confirmation prompt")

	// Accept the bead-id either before or after flags. We pull the first
	// non-flag positional out of args, then let the standard flag parser
	// handle the rest.
	beadID, parseArgs := extractFirstPositional(args)
	if err := fs.Parse(parseArgs); err != nil {
		return 2
	}
	if beadID == "" {
		fmt.Fprintln(os.Stderr, "usage: ddx-agent corpus promote <bead-id> [flags]")
		return 2
	}
	if fs.NArg() > 0 {
		fmt.Fprintf(os.Stderr, "error: unexpected positional argument(s): %v\n", fs.Args())
		return 2
	}

	root := filepath.Join(workDir, corpusRoot)

	loaded, err := corpus.Load(root)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: load corpus: %v\n", err)
		return 1
	}
	if loaded.HasBead(beadID) {
		fmt.Fprintf(os.Stderr, "error: bead %q is already in corpus.yaml\n", beadID)
		return 1
	}

	bead, err := loadBeadFromJSONL(filepath.Join(workDir, ".ddx", "beads.jsonl"), beadID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		return 1
	}
	if !strings.EqualFold(bead.Status, "closed") {
		fmt.Fprintf(os.Stderr, "error: bead %q is not closed (status=%q); promotion only accepts closed beads\n", beadID, bead.Status)
		return 1
	}

	resolvedBase := strings.TrimSpace(*baseRev)
	if resolvedBase == "" {
		resolvedBase = bead.ParentCommitSHA
	}
	resolvedGood := strings.TrimSpace(*knownGoodRev)
	if resolvedGood == "" {
		resolvedGood = bead.ClosingCommitSHA
	}
	if resolvedGood == "" {
		fmt.Fprintf(os.Stderr,
			"error: bead %q has no closing_commit_sha and no --known-good-rev was provided\n", beadID)
		return 1
	}
	if resolvedBase == "" {
		fmt.Fprintf(os.Stderr,
			"error: bead %q has no parent_commit_sha and no --base-rev was provided\n", beadID)
		return 1
	}

	pr := strings.TrimSpace(*projectRoot)
	if pr == "" {
		pr = workDir
	}
	by := strings.TrimSpace(*promotedBy)
	if by == "" {
		by = os.Getenv("USER")
	}
	if by == "" {
		by = "unknown"
	}

	req := corpus.PromoteRequest{
		BeadID:       beadID,
		ProjectRoot:  pr,
		BaseRev:      resolvedBase,
		KnownGoodRev: resolvedGood,
		Captured:     time.Now().UTC().Format("2006-01-02"),
		PromotedBy:   by,
		Capability:   strings.TrimSpace(*capability),
		FailureMode:  strings.TrimSpace(*failureMode),
		Difficulty:   strings.TrimSpace(*difficulty),
		PromptKind:   strings.TrimSpace(*promptKind),
		Notes:        *notes,

